window.__finlexDocLoaded(10135,{"id":10135,"articles":[{"id":1000589,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"SIC-10 clarifies that government assistance to entities that is aimed at encouragement or long-term support of business activities either in certain regions or industry sectors should be accounted for as a government grant under IAS 20. Therefore, such grants should not be credited directly to shareholders' equity even if the grant does not contain any conditions specifically relating to the operating activities of the entity.","seq":0},{"id":1000590,"no":"SIC-10.3","heading":"Government Assistance — No Specific Operating Relation","text":"Government assistance aimed at encouraging long-term business activity in specific regions or sectors qualifies as a government grant under IAS 20 and must NOT be credited directly to shareholders' equity.","seq":1},{"id":1000591,"no":"History","heading":"Standard History & Amendments","text":"In April 2001 the International Accounting Standards Board adopted SIC‑10 Government Assistance—No Specific Relation to Operating Activities, which had originally been issued by the Standing Interpretations Committee of the International Accounting Standards Committee in July 1998.","seq":2},{"id":1000592,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related IFRS Standards]\n• IAS 20 Accounting for Government Grants and Disclosure of Government Assistance","seq":3},{"id":1000593,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/sic-10-government-assistance-no-specific-relation-to-operating-activities/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":4}]});
